#!/bin/bash

# Auto-Build Environment Setup for Spec 043
# Generated by Planner Agent

set -e

echo "========================================"
echo "Bop Gantt HTML Polish - Environment Setup"
echo "========================================"

# Colors
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'

# ============================================
# VERIFY RUST TOOLCHAIN
# ============================================

echo "Checking Rust toolchain..."
if ! command -v cargo &> /dev/null; then
    echo -e "${RED}Error: cargo not found. Please install Rust.${NC}"
    exit 1
fi

echo -e "${GREEN}Rust toolchain found${NC}"
cargo --version
rustc --version

# ============================================
# BUILD PROJECT
# ============================================

echo ""
echo "Building bop-cli..."
cargo build --package bop-cli

if [ $? -eq 0 ]; then
    echo -e "${GREEN}Build successful${NC}"
else
    echo -e "${RED}Build failed${NC}"
    exit 1
fi

# ============================================
# RUN TESTS
# ============================================

echo ""
echo "Running tests..."
cargo test --package bop-cli -- gantt::tests --nocapture

if [ $? -eq 0 ]; then
    echo -e "${GREEN}Tests passed${NC}"
else
    echo -e "${YELLOW}Some tests may have failed - review output above${NC}"
fi

# ============================================
# SUMMARY
# ============================================

echo ""
echo "========================================"
echo "Environment Ready!"
echo "========================================"
echo ""
echo "Next steps:"
echo "  1. Review existing gantt.rs implementation"
echo "  2. Test HTML generation: ./target/debug/bop gantt --html -o"
echo "  3. Verify tooltips, heatmap, and summary stats"
echo "  4. Run lint check: cargo clippy --package bop-cli -- -D warnings"
echo ""
echo "Binary location: ./target/debug/bop"
echo ""
